            if is_prime[p] and num % p == 0:
                prime_factors[p].append(num)
                while num % p == 0:
                    num //= p
        if num > 1:
            prime_factors[num].append(num)

    operations = 0
    for p in sorted(prime_factors.keys()):
        operations += len(prime_factors[p])

    return operations

