        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                end = (i, j)

    # BFS to find the shortest path from S to T
    queue = deque([start])
    visited = set([start])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    steps = 0

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()
            if (x, y) == end:
